import React, { useState, useEffect } from 'react';
import axios from 'axios';
import '../../../styles/GlobalStyles.css';

const AttendeeDashboard = () => {
  // State variables to hold the events, loading status, and any error messages.
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Function to fetch events for the attendee from the backend.
  const fetchEvents = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem('token'); // Assume token is stored here after login.
      const response = await axios.get('http://localhost:5000/api/attendee/events', {
        headers: { Authorization: `Bearer ${token}` }
      });
      // Set the fetched events into state
      setEvents(response.data.events);
      setLoading(false);
      setError(null);
    } catch (err) {
      setError('Failed to fetch events');
      setLoading(false);
    }
  };

  // useEffect to fetch events on mount and set polling every 30 seconds.
  useEffect(() => {
    fetchEvents();
    const intervalId = setInterval(fetchEvents, 30000); // Poll every 30 seconds
    return () => clearInterval(intervalId);
  }, []);

  return (
    <div className="container">
      <div className="card">
        <h2>Attendee Dashboard</h2>
        <p>View your registered events, check your tickets, and join live sessions.</p>
        
        {/* Personalized Schedule Section */}
        <section>
          <h3>Personalized Schedule</h3>
          {loading ? (
            <p>Loading events...</p>
          ) : error ? (
            <p style={{ color: 'red' }}>{error}</p>
          ) : events.length > 0 ? (
            <ul>
              {events.map(event => (
                <li key={event._id} style={{ marginBottom: '0.5rem' }}>
                  <strong>{event.title}</strong> | Date: {new Date(event.date).toLocaleDateString()}<br />
                  Ticket Type: {event.ticketType || 'General'}<br />
                  Session Link: <a href={event.sessionLink} style={{ color: '#bb86fc' }}>Join Session</a>
                </li>
              ))}
            </ul>
          ) : (
            <p>No registered events found.</p>
          )}
        </section>
        
        {/* Engagement Tools Section */}
        <section style={{ marginTop: '2rem' }}>
          <h3>Engagement Tools</h3>
          <button className="btn" style={{ marginRight: '1rem' }}>Join Live Chat</button>
          <button className="btn">Participate in Q&amp;A</button>
        </section>
        
        {/* Feedback & Support Section */}
        <section style={{ marginTop: '2rem' }}>
          <h3>Feedback &amp; Support</h3>
          <p>If you have any issues or feedback, let us know.</p>
          <input 
            type="text" 
            placeholder="Type your feedback here..." 
            style={{ 
              width: '100%', 
              padding: '0.5rem', 
              borderRadius: '4px', 
              border: '1px solid #444', 
              backgroundColor: '#1e1e1e', 
              color: '#e0e0e0' 
            }}
          />
          <button className="btn" style={{ marginTop: '1rem' }}>Submit Feedback</button>
        </section>
      </div>
    </div>
  );
};

export default AttendeeDashboard;
